/**
 * Cloudflare Worker entry: the OpenNext-built Next.js app, plus a nightly
 * scheduled backup of the D1 database into the private BACKUPS bucket.
 * (`wrangler.jsonc` points `main` here; `.open-next/worker.js` is generated by
 * `opennextjs-cloudflare build`.)
 */
// @ts-ignore — generated at build time
import { default as nextHandler } from './.open-next/worker.js';
import { backupD1ToR2 } from './src/server/backup/d1-dump';

interface Env {
  DB?: D1Database;
  BACKUPS?: R2Bucket;
}

export default {
  fetch: nextHandler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    if (!env.DB || !env.BACKUPS) {
      console.warn(
        '[backup] skipped: DB or BACKUPS binding missing (Postgres deployments back up at the database)',
      );
      return;
    }
    ctx.waitUntil(
      backupD1ToR2(env.DB, env.BACKUPS, new Date(controller.scheduledTime)).then(
        (result) =>
          console.log(`[backup] wrote ${result.key}: ${result.tables} tables, ${result.rows} rows`),
        (error) => console.error('[backup] failed', error),
      ),
    );
  },
} satisfies ExportedHandler<Env>;
